package com.tithefarmtooltip;

import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class TitheFruitTest
{
	@Test
	public void mapsAllTitheFruitItemIds()
	{
		assertEquals(TitheFruit.GOLOVANOVA, TitheFruit.fromItemId(ItemID.HOSIDIUS_TITHE_FRUIT_A));
		assertEquals(TitheFruit.BOLOGANO, TitheFruit.fromItemId(ItemID.HOSIDIUS_TITHE_FRUIT_B));
		assertEquals(TitheFruit.LOGAVANO, TitheFruit.fromItemId(ItemID.HOSIDIUS_TITHE_FRUIT_C));
		assertNull(TitheFruit.fromItemId(-1));
	}

	@Test
	public void calculatesLogavanoThresholdsWithoutOutfit()
	{
		assertEquals(23_000L, TitheFruit.LOGAVANO.getTurnInXpHundredths(1, false));
		assertEquals(1_702_000L, TitheFruit.LOGAVANO.getTurnInXpHundredths(74, false));
		assertEquals(2_323_000L, TitheFruit.LOGAVANO.getTurnInXpHundredths(75, false));
		assertEquals(3_473_000L, TitheFruit.LOGAVANO.getTurnInXpHundredths(100, false));
	}

	@Test
	public void calculatesEveryFruitAndRepeatedBatches()
	{
		assertEquals(906_000L, TitheFruit.GOLOVANOVA.getTurnInXpHundredths(100, false));
		assertEquals(2_114_000L, TitheFruit.BOLOGANO.getTurnInXpHundredths(100, false));
		assertEquals(6_946_000L, TitheFruit.LOGAVANO.getTurnInXpHundredths(200, false));
	}

	@Test
	public void appliesOutfitOnlyToDepositXp()
	{
		assertEquals(3_545_450L, TitheFruit.LOGAVANO.getTurnInXpHundredths(100, true));
		assertEquals(2_158_100L, TitheFruit.BOLOGANO.getTurnInXpHundredths(100, true));
		assertEquals(924_900L, TitheFruit.GOLOVANOVA.getTurnInXpHundredths(100, true));
	}
}

package com.tithefarmtooltip;

import net.runelite.api.Experience;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class TitheFarmCalculatorTest
{
	@Test
	public void calculatesProgressFromExactLevel81()
	{
		TitheFarmCalculator.TurnInResult result = TitheFarmCalculator.calculate(
			TitheFruit.LOGAVANO,
			100,
			false,
			Experience.getXpForLevel(81));

		assertEquals(3_473_000L, result.getGainedXpHundredths());
		assertEquals(81, result.getCurrentLevel());
		assertEquals(81, result.getEndingLevel());
		assertEquals(0, result.getLevelsGained());
		assertEquals(19_353_900L, result.getXpToNextLevelHundredths());
	}

	@Test
	public void reportsMultipleLevelsGained()
	{
		TitheFarmCalculator.TurnInResult result = TitheFarmCalculator.calculate(
			TitheFruit.LOGAVANO,
			2_000,
			false,
			Experience.getXpForLevel(81));

		assertEquals(81, result.getCurrentLevel());
		assertEquals(83, result.getEndingLevel());
		assertEquals(2, result.getLevelsGained());
	}

	@Test
	public void capsLevelsAt99()
	{
		TitheFarmCalculator.TurnInResult result = TitheFarmCalculator.calculate(
			TitheFruit.LOGAVANO,
			100,
			false,
			Experience.getXpForLevel(99));

		assertEquals(99, result.getCurrentLevel());
		assertEquals(99, result.getEndingLevel());
		assertEquals(0, result.getLevelsGained());
		assertEquals(0, result.getXpToNextLevelHundredths());
	}
}

