package com.tithefarmtooltip;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.Experience;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class TitheFarmTooltipGoldenTableTest
{
	private static final int STARTING_LEVEL = 81;
	private static final int STARTING_XP = Experience.getXpForLevel(STARTING_LEVEL);
	private static final int MAX_QUANTITY = 10_000;

	@Test
	public void everyTooltipMatchesTheGoldenTableThroughTenThousandFruit() throws IOException
	{
		InputStream input = getClass().getResourceAsStream("/tithe-farm-tooltip-cases.csv");
		assertNotNull("golden tooltip table is missing", input);

		try (BufferedReader reader = new BufferedReader(
			new InputStreamReader(input, StandardCharsets.US_ASCII)))
		{
			String headerLine = reader.readLine();
			assertNotNull("golden tooltip table has no header", headerLine);
			Map<String, Integer> columns = indexColumns(headerLine);
			String line;
			int expectedQuantity = 1;

			while ((line = reader.readLine()) != null)
			{
				String[] values = line.split(",", -1);
				int quantity = Integer.parseInt(value(values, columns, "quantity"));
				assertEquals("table quantity sequence", expectedQuantity, quantity);

				for (TitheFruit fruit : TitheFruit.values())
				{
					assertTooltipCase(values, columns, fruit, quantity, false);
					assertTooltipCase(values, columns, fruit, quantity, true);
				}
				expectedQuantity++;
			}

			assertEquals("golden table row count", MAX_QUANTITY + 1, expectedQuantity);
		}
	}

	private static void assertTooltipCase(
		String[] values,
		Map<String, Integer> columns,
		TitheFruit fruit,
		int quantity,
		boolean outfit)
	{
		String prefix = fruit.name().toLowerCase(Locale.ROOT) + (outfit ? "_outfit" : "");
		long expectedXp = Long.parseLong(value(values, columns, prefix + "_xp_hundredths"));
		int expectedEndingLevel = Integer.parseInt(value(values, columns, prefix + "_ending_level"));
		long expectedToNext = Long.parseLong(value(values, columns, prefix + "_to_next_hundredths"));

		TitheFarmCalculator.TurnInResult result = TitheFarmCalculator.calculate(
			fruit,
			quantity,
			outfit,
			STARTING_XP);

		String caseName = fruit + " quantity=" + quantity + " outfit=" + outfit;
		assertEquals(caseName + " XP", expectedXp, result.getGainedXpHundredths());
		assertEquals(caseName + " current level", STARTING_LEVEL, result.getCurrentLevel());
		assertEquals(caseName + " ending level", expectedEndingLevel, result.getEndingLevel());
		assertEquals(caseName + " levels gained", expectedEndingLevel - STARTING_LEVEL, result.getLevelsGained());
		assertEquals(caseName + " XP to next level", expectedToNext, result.getXpToNextLevelHundredths());

		String expectedTooltip = expectedTooltip(
			fruit,
			quantity,
			outfit,
			expectedXp,
			expectedEndingLevel,
			expectedToNext);
		assertEquals(caseName + " tooltip", expectedTooltip,
			TitheFarmTooltipFormatter.format(fruit, quantity, outfit, result));
	}

	private static String expectedTooltip(
		TitheFruit fruit,
		int quantity,
		boolean outfit,
		long gainedXpHundredths,
		int endingLevel,
		long toNextHundredths)
	{
		int levelsGained = endingLevel - STARTING_LEVEL;
		StringBuilder expected = new StringBuilder()
			.append(quantity)
			.append(' ')
			.append(fruit.getDisplayName())
			.append(" fruit")
			.append("<br>Turn-in XP: ")
			.append(formatHundredths(gainedXpHundredths))
			.append("<br>Farming: ")
			.append(STARTING_LEVEL)
			.append(" -> ")
			.append(endingLevel)
			.append(" (+")
			.append(levelsGained)
			.append(levelsGained == 1 ? " level)" : " levels)");

		if (endingLevel < 99)
		{
			expected.append("<br>To level ")
				.append(endingLevel + 1)
				.append(": ")
				.append(formatHundredths(toNextHundredths))
				.append(" XP");
		}
		if (outfit)
		{
			expected.append("<br>Full farmer's outfit included");
		}
		return expected.toString();
	}

	private static String formatHundredths(long xpHundredths)
	{
		long whole = xpHundredths / 100;
		int fraction = (int) Math.abs(xpHundredths % 100);
		String formattedWhole = String.format(Locale.US, "%,d", whole);
		if (fraction == 0)
		{
			return formattedWhole;
		}
		if (fraction % 10 == 0)
		{
			return formattedWhole + "." + fraction / 10;
		}
		return formattedWhole + "." + String.format(Locale.US, "%02d", fraction);
	}

	private static Map<String, Integer> indexColumns(String headerLine)
	{
		String[] headers = headerLine.split(",", -1);
		Map<String, Integer> columns = new HashMap<>();
		for (int index = 0; index < headers.length; index++)
		{
			columns.put(headers[index], index);
		}
		return columns;
	}

	private static String value(String[] values, Map<String, Integer> columns, String column)
	{
		Integer index = columns.get(column);
		if (index == null)
		{
			throw new AssertionError("Missing golden table column: " + column);
		}
		return values[index];
	}
}

package com.tithefarmtooltip;

import net.runelite.api.Experience;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class TitheFarmTooltipFormatterTest
{
	@Test
	public void formatsFractionalXpWithoutTrailingZeroes()
	{
		assertEquals("35,454.5", TitheFarmTooltipFormatter.formatHundredths(3_545_450));
		assertEquals("230", TitheFarmTooltipFormatter.formatHundredths(23_000));
		assertEquals("235.75", TitheFarmTooltipFormatter.formatHundredths(23_575));
	}

	@Test
	public void includesRequestedTooltipDetails()
	{
		TitheFarmCalculator.TurnInResult result = TitheFarmCalculator.calculate(
			TitheFruit.LOGAVANO,
			100,
			true,
			Experience.getXpForLevel(81));
		String tooltip = TitheFarmTooltipFormatter.format(TitheFruit.LOGAVANO, 100, true, result);

		assertTrue(tooltip.contains("100 Logavano fruit"));
		assertTrue(tooltip.contains("Turn-in XP: 35,454.5"));
		assertTrue(tooltip.contains("Farming: 81 -> 81 (+0 levels)"));
		assertTrue(tooltip.contains("Full farmer's outfit included"));
	}
}

package com.tithefarmtooltip;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.Skill;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.RuneLite;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.externalplugins.ExternalPluginManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

@PluginDescriptor(
	name = "Tithe Farm Tooltip",
	description = "Shows Farming XP and levels gained when hovering over Tithe Farm fruit"
)
public class TitheFarmTooltipPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private TooltipManager tooltipManager;

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		if (client.isMenuOpen())
		{
			return;
		}

		MenuEntry[] menuEntries = client.getMenu().getMenuEntries();
		if (menuEntries.length == 0)
		{
			return;
		}

		MenuEntry menuEntry = menuEntries[menuEntries.length - 1];
		if (WidgetUtil.componentToInterface(menuEntry.getParam1()) != InterfaceID.INVENTORY)
		{
			return;
		}

		Widget itemWidget = menuEntry.getWidget();
		if (itemWidget == null || itemWidget.getItemQuantity() <= 0)
		{
			return;
		}

		TitheFruit fruit = TitheFruit.fromItemId(itemWidget.getItemId());
		if (fruit == null)
		{
			return;
		}

		boolean fullFarmerOutfit = FarmerOutfit.isWearingFullSet(
			client.getItemContainer(InventoryID.WORN));
		TitheFarmCalculator.TurnInResult result = TitheFarmCalculator.calculate(
			fruit,
			itemWidget.getItemQuantity(),
			fullFarmerOutfit,
			client.getSkillExperience(Skill.FARMING));

		tooltipManager.add(new Tooltip(TitheFarmTooltipFormatter.format(
			fruit,
			itemWidget.getItemQuantity(),
			fullFarmerOutfit,
			result)));
	}

	@SuppressWarnings("unchecked")
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(TitheFarmTooltipPlugin.class);
		RuneLite.main(args);
	}
}

package com.tithefarmtooltip;

import net.runelite.api.gameval.ItemID;

enum TitheFruit
{
	GOLOVANOVA(ItemID.HOSIDIUS_TITHE_FRUIT_A, "Golovanova", 60, 1_500),
	BOLOGANO(ItemID.HOSIDIUS_TITHE_FRUIT_B, "Bologano", 140, 3_500),
	LOGAVANO(ItemID.HOSIDIUS_TITHE_FRUIT_C, "Logavano", 230, 5_750);

	private static final int BATCH_SIZE = 100;
	private static final int BONUS_THRESHOLD = 75;
	private static final int OUTFIT_MULTIPLIER_NUMERATOR = 41;
	private static final int OUTFIT_MULTIPLIER_DENOMINATOR = 40;

	private final int itemId;
	private final String displayName;
	private final int depositXp;
	private final int batchBonusXp;

	TitheFruit(int itemId, String displayName, int depositXp, int batchBonusXp)
	{
		this.itemId = itemId;
		this.displayName = displayName;
		this.depositXp = depositXp;
		this.batchBonusXp = batchBonusXp;
	}

	int getItemId()
	{
		return itemId;
	}

	String getDisplayName()
	{
		return displayName;
	}

	long getTurnInXpHundredths(int quantity, boolean fullFarmerOutfit)
	{
		if (quantity <= 0)
		{
			return 0;
		}

		int fullBatches = quantity / BATCH_SIZE;
		int remainder = quantity % BATCH_SIZE;
		return (long) fullBatches * getPartialBatchXpHundredths(BATCH_SIZE, fullFarmerOutfit)
			+ getPartialBatchXpHundredths(remainder, fullFarmerOutfit);
	}

	private long getPartialBatchXpHundredths(int quantity, boolean fullFarmerOutfit)
	{
		if (quantity <= 0)
		{
			return 0;
		}

		long baseXpHundredths = depositXp * 100L;
		if (fullFarmerOutfit)
		{
			baseXpHundredths = baseXpHundredths * OUTFIT_MULTIPLIER_NUMERATOR
				/ OUTFIT_MULTIPLIER_DENOMINATOR;
		}

		int normalFruit = Math.min(quantity, BONUS_THRESHOLD - 1);
		int doubledFruit = Math.max(0, quantity - normalFruit);
		long xpHundredths = baseXpHundredths * (normalFruit + 2L * doubledFruit);

		if (quantity >= BONUS_THRESHOLD)
		{
			xpHundredths += batchBonusXp * 100L;
		}

		return xpHundredths;
	}

	static TitheFruit fromItemId(int itemId)
	{
		for (TitheFruit fruit : values())
		{
			if (fruit.itemId == itemId)
			{
				return fruit;
			}
		}
		return null;
	}
}

package com.tithefarmtooltip;

import java.util.Locale;

final class TitheFarmTooltipFormatter
{
	private TitheFarmTooltipFormatter()
	{
	}

	static String format(
		TitheFruit fruit,
		int quantity,
		boolean fullFarmerOutfit,
		TitheFarmCalculator.TurnInResult result)
	{
		int levelsGained = result.getLevelsGained();
		String levelWord = levelsGained == 1 ? "level" : "levels";
		StringBuilder tooltip = new StringBuilder()
			.append(quantity)
			.append(' ')
			.append(fruit.getDisplayName())
			.append(" fruit")
			.append("<br>Turn-in XP: ")
			.append(formatHundredths(result.getGainedXpHundredths()))
			.append("<br>Farming: ")
			.append(result.getCurrentLevel())
			.append(" -> ")
			.append(result.getEndingLevel())
			.append(" (+")
			.append(levelsGained)
			.append(' ')
			.append(levelWord)
			.append(')');

		if (result.getEndingLevel() < 99)
		{
			tooltip.append("<br>To level ")
				.append(result.getEndingLevel() + 1)
				.append(": ")
				.append(formatHundredths(result.getXpToNextLevelHundredths()))
				.append(" XP");
		}

		if (fullFarmerOutfit)
		{
			tooltip.append("<br>Full farmer's outfit included");
		}

		return tooltip.toString();
	}

	static String formatHundredths(long xpHundredths)
	{
		long whole = xpHundredths / 100;
		int fraction = (int) Math.abs(xpHundredths % 100);
		String formattedWhole = String.format(Locale.US, "%,d", whole);
		if (fraction == 0)
		{
			return formattedWhole;
		}
		if (fraction % 10 == 0)
		{
			return formattedWhole + "." + fraction / 10;
		}
		return formattedWhole + "." + String.format(Locale.US, "%02d", fraction);
	}
}

package com.tithefarmtooltip;

import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.ItemID;

final class FarmerOutfit
{
	private FarmerOutfit()
	{
	}

	static boolean isWearingFullSet(ItemContainer equipment)
	{
		if (equipment == null)
		{
			return false;
		}

		Item[] items = equipment.getItems();
		int[] itemIds = new int[items.length];
		for (int index = 0; index < items.length; index++)
		{
			itemIds[index] = items[index].getId();
		}
		return isFullSet(itemIds);
	}

	static boolean isFullSet(int... itemIds)
	{
		boolean hat = false;
		boolean torso = false;
		boolean legs = false;
		boolean feet = false;

		for (int itemId : itemIds)
		{
			hat |= itemId == ItemID.TITHE_REWARD_HAT_MALE || itemId == ItemID.TITHE_REWARD_HAT_FEMALE;
			torso |= itemId == ItemID.TITHE_REWARD_TORSO_MALE || itemId == ItemID.TITHE_REWARD_TORSO_FEMALE;
			legs |= itemId == ItemID.TITHE_REWARD_LEGS_MALE || itemId == ItemID.TITHE_REWARD_LEGS_FEMALE;
			feet |= itemId == ItemID.TITHE_REWARD_FEET_MALE || itemId == ItemID.TITHE_REWARD_FEET_FEMALE;
		}

		return hat && torso && legs && feet;
	}
}

package com.tithefarmtooltip;

import net.runelite.api.Experience;

final class TitheFarmCalculator
{
	private static final int MAX_LEVEL = 99;
	private static final int HUNDREDTHS_PER_XP = 100;

	private TitheFarmCalculator()
	{
	}

	static TurnInResult calculate(TitheFruit fruit, int quantity, boolean fullFarmerOutfit, int currentXp)
	{
		if (fruit == null)
		{
			throw new IllegalArgumentException("fruit must not be null");
		}
		if (quantity < 0)
		{
			throw new IllegalArgumentException("quantity must not be negative");
		}

		int safeCurrentXp = Math.max(0, currentXp);
		long gainedXpHundredths = fruit.getTurnInXpHundredths(quantity, fullFarmerOutfit);
		long endingXpHundredths = safeCurrentXp * (long) HUNDREDTHS_PER_XP + gainedXpHundredths;
		int currentLevel = levelForXpHundredths(safeCurrentXp * (long) HUNDREDTHS_PER_XP);
		int endingLevel = levelForXpHundredths(endingXpHundredths);
		long xpToNextLevelHundredths = endingLevel >= MAX_LEVEL
			? 0
			: Math.max(0, Experience.getXpForLevel(endingLevel + 1) * (long) HUNDREDTHS_PER_XP
				- endingXpHundredths);

		return new TurnInResult(
			gainedXpHundredths,
			currentLevel,
			endingLevel,
			xpToNextLevelHundredths);
	}

	private static int levelForXpHundredths(long xpHundredths)
	{
		for (int level = MAX_LEVEL; level >= 1; level--)
		{
			if (xpHundredths >= Experience.getXpForLevel(level) * (long) HUNDREDTHS_PER_XP)
			{
				return level;
			}
		}
		return 1;
	}

	static final class TurnInResult
	{
		private final long gainedXpHundredths;
		private final int currentLevel;
		private final int endingLevel;
		private final long xpToNextLevelHundredths;

		private TurnInResult(
			long gainedXpHundredths,
			int currentLevel,
			int endingLevel,
			long xpToNextLevelHundredths)
		{
			this.gainedXpHundredths = gainedXpHundredths;
			this.currentLevel = currentLevel;
			this.endingLevel = endingLevel;
			this.xpToNextLevelHundredths = xpToNextLevelHundredths;
		}

		long getGainedXpHundredths()
		{
			return gainedXpHundredths;
		}

		int getCurrentLevel()
		{
			return currentLevel;
		}

		int getEndingLevel()
		{
			return endingLevel;
		}

		int getLevelsGained()
		{
			return endingLevel - currentLevel;
		}

		long getXpToNextLevelHundredths()
		{
			return xpToNextLevelHundredths;
		}
	}
}
